		inst.on('foo', foo);
		inst.off('foo', foo);

		expect(events.get('foo')).to.be.empty;
	});

	it('should NOT normalize case', () => {
		const foo = () => {};
		inst.on('FOO', foo);
		inst.on('Bar', foo);
		inst.on('baz:bat!', foo);

